def update_fixes():
    print("Fixing remaining short comments to 350+ chars...\n")
    
    success_count = 0
    for code, comment in fix_comments.items():
        char_count = len(comment)
        url = f"{SUPABASE_URL}/rest/v1/majors?code=eq.{code}"
        response = requests.patch(url, headers=headers, json={"xuefeng_comment": comment})
        
        if response.status_code in [200, 204]:
            status = "✅" if char_count >= 350 else "⚠️"
            print(f"{status} {code} ({char_count} chars)")
            success_count += 1
        else:
            print(f"❌ {code}: {response.status_code}")
    
    print(f"\nCompleted: {success_count} fixes applied")

if __name__ == "__main__":
    update_fixes()
